widget.solution:
import numpy as np

def decile_means(r, J):
    f = formation_returns(r, J)
    T, n = r.shape
    total = np.zeros(10)
    for t in range(J, T):
        rank = np.argsort(np.argsort(f[t], kind="stable"), kind="stable")
        dec = rank * 10 // n
        total += np.array([r[t][dec == k].mean() for k in range(10)])
    return total / (T - J)
